package br.com.onda;
import java.net.*;
import java.util.*;
import org.json.*;
/** One anonymous public-media attempt. Never imports account or WebView cookies. */
final class MediaSession {
 static final int MAX=24,SNAPSHOT=32768;
 private static final class Cookie {String name,value,domain,path;boolean hostOnly,secure;long expires;}
 private final List<Cookie> cookies=new ArrayList<>();
 private static boolean service(String h){if(h==null)return false;h=h.toLowerCase(Locale.ROOT);for(String base:new String[]{"tiktok.com","tiktokcdn.com","tiktokcdn-us.com","tiktokv.com","byteoversea.com","ibytedtos.com","muscdn.com"})if(h.equals(base)||h.endsWith("."+base))return true;return false;}
 private static boolean value(String s){if(s==null||s.length()>4096)return false;for(int i=0;i<s.length();i++){char c=s.charAt(i);if(c<=32||c>=127||c==';'||c==','||c=='"'||c=='\\')return false;}return true;}
 private static boolean valid(Cookie c){return c.name!=null&&c.name.matches("[A-Za-z0-9_.-]{1,80}")&&value(c.value)&&service(c.domain)&&c.domain.length()<=253&&c.domain.matches("[a-z0-9.-]+")&&!c.domain.contains("..")&&c.path!=null&&c.path.startsWith("/")&&c.path.length()<=2048&&c.path.matches("[^\\p{Cntrl}]*");}
 private void store(Cookie c){cookies.removeIf(old->old.name.equals(c.name)&&old.domain.equals(c.domain)&&old.path.equals(c.path));if(c.expires==0||!valid(c))return;while(cookies.size()>=MAX)cookies.remove(0);cookies.add(c);}
 synchronized void receive(String target,Map<String,List<String>> headers){try{URI uri=new URI(target);String host=uri.getHost();if(!"https".equalsIgnoreCase(uri.getScheme())||!service(host)||headers==null)return;host=host.toLowerCase(Locale.ROOT);long now=System.currentTimeMillis();int count=0;for(Map.Entry<String,List<String>> e:headers.entrySet()){if(e.getKey()==null||!e.getKey().equalsIgnoreCase("Set-Cookie")||e.getValue()==null)continue;for(String line:e.getValue()){if(++count>32)return;if(line==null||line.length()>8192)continue;try{for(HttpCookie parsed:HttpCookie.parse(line)){Cookie c=new Cookie();c.name=parsed.getName();c.value=parsed.getValue();c.hostOnly=parsed.getDomain()==null;c.domain=c.hostOnly?host:parsed.getDomain().toLowerCase(Locale.ROOT).replaceFirst("^\\.","");if(!service(c.domain)||!(host.equals(c.domain)||host.endsWith("."+c.domain)))continue;c.path=parsed.getPath();if(c.path==null||!c.path.startsWith("/")){String p=uri.getPath();int slash=p==null?-1:p.lastIndexOf('/');c.path=slash<=0?"/":p.substring(0,slash);}c.secure=parsed.getSecure();long age=parsed.getMaxAge();c.expires=age==0?0:age<0?-1:age>(Long.MAX_VALUE-now)/1000?Long.MAX_VALUE:now+age*1000;store(c);}}catch(IllegalArgumentException ignored){}}}}catch(Exception ignored){}}
 synchronized String header(String target){try{URI uri=new URI(target);String host=uri.getHost();if(host==null||!"https".equalsIgnoreCase(uri.getScheme())||!service(host))return "";host=host.toLowerCase(Locale.ROOT);String path=uri.getPath();if(path==null||path.isEmpty())path="/";long now=System.currentTimeMillis();cookies.removeIf(c->c.expires>=0&&c.expires<=now);List<Cookie> matches=new ArrayList<>();for(Cookie c:cookies){if(!(host.equals(c.domain)||(!c.hostOnly&&host.endsWith("."+c.domain))))continue;if(!(path.equals(c.path)||(path.startsWith(c.path)&&(c.path.endsWith("/")||(path.length()>c.path.length()&&path.charAt(c.path.length())=='/')))))continue;matches.add(c);}matches.sort((a,b)->Integer.compare(b.path.length(),a.path.length()));StringBuilder out=new StringBuilder();for(Cookie c:matches){if(out.length()>0)out.append("; ");out.append(c.name).append('=').append(c.value);}return out.length()<=SNAPSHOT?out.toString():"";}catch(Exception ignored){return "";}}
 synchronized String snapshot(){try{JSONArray a=new JSONArray();long now=System.currentTimeMillis();for(Cookie c:cookies)if(c.expires<0||c.expires>now)a.put(new JSONObject().put("name",c.name).put("value",c.value).put("domain",c.domain).put("path",c.path).put("hostOnly",c.hostOnly).put("secure",c.secure).put("expires",c.expires));String raw=new JSONObject().put("version",1).put("cookies",a).toString();return raw.length()<=SNAPSHOT?raw:"";}catch(JSONException e){return "";}}
 static MediaSession restore(String raw)throws java.io.IOException{MediaSession session=new MediaSession();if(raw==null||raw.isEmpty())return session;try{if(raw.length()>SNAPSHOT)throw new JSONException("size");JSONObject root=new JSONObject(raw);if(!Integer.valueOf(1).equals(root.opt("version")))throw new JSONException("version");JSONArray a=root.getJSONArray("cookies");if(a.length()>MAX)throw new JSONException("count");for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);Cookie c=new Cookie();c.name=o.getString("name");c.value=o.getString("value");c.domain=o.getString("domain");c.path=o.getString("path");c.hostOnly=o.getBoolean("hostOnly");c.secure=o.getBoolean("secure");c.expires=o.getLong("expires");if(!valid(c)||!c.domain.equals(c.domain.toLowerCase(Locale.ROOT))||c.domain.startsWith(".")||c.expires< -1)throw new JSONException("cookie");session.store(c);}return session;}catch(JSONException e){throw new java.io.IOException("A sessão pública expirou ou ficou inválida. Analise o link novamente.",e);}}
}
